import{_ as i,c as l,e as a,o as t}from"./index-DUl6PKBW.js";const c={},r={class:"container my-5"};function d(o,s){return t(),l("div",r,s[0]||(s[0]=[a('<div class="text-center mb-5"><h1 class="display-4">IX Российская научно-практическая конференция</h1><p class="lead"> 30 октября 2018 г. | Центр нейрохирургии им. Н.Н. Бурденко </p></div><div class="alert alert-info mt-4"><strong>Годы проведения: </strong><a href="#" class="link-primary text-decoration-none">2016</a>, <a href="/educational/2017" class="link-primary text-decoration-none">2017</a>, <a href="/educational/2018" class="link-primary text-decoration-none">2018</a></div><div class="card mb-4"><div class="card-body"><h2 class="h4 card-title">Приглашение к участию</h2><p> Приглашаем специалистов всех медицинских направлений, разработчиков медицинской техники, а также врачей всех специальностей. Участие бесплатное. Заявка в Совет НМО подана для начисления образовательных баллов по специальности &quot;Неврология&quot;. </p></div></div><div class="row mb-4"><div class="col-md-6"><div class="card h-100"><div class="card-body"><h5 class="card-title">Научный руководитель</h5><p class="card-text"><strong>Владимир Иванович Шмырев</strong> — д.м.н., профессор, заведующий кафедрой неврологии ФГБУ «ЦГМА» УД Президента РФ. </p></div></div></div><div class="col-md-6"><div class="card h-100"><div class="card-body"><h5 class="card-title">Научный секретарь</h5><p class="card-text"><strong>Алексей Сергеевич Васильев</strong> — к.м.н., доцент кафедры неврологии ФГБУ «ЦГМА» УД Президента РФ. </p></div></div></div></div><div class="card mb-4"><div class="card-body"><h2 class="h4">Основные темы конференции</h2><ul class="list-group list-group-flush mt-3"><li class="list-group-item"> Острые и хронические нарушения мозгового кровообращения </li><li class="list-group-item"> Ангионеврология и когнитивные расстройства </li><li class="list-group-item"> Альгология (болевые синдромы, мигрени) </li><li class="list-group-item">Нейроонкология</li><li class="list-group-item">Нейрореабилитация</li><li class="list-group-item">Неврология и внутренняя медицина</li><li class="list-group-item">Возрастные аспекты неврологии</li><li class="list-group-item"> Дегенеративные заболевания нервной системы </li><li class="list-group-item">Пароксизмальные состояния</li><li class="list-group-item">Нейроинфекции</li><li class="list-group-item"> Дизиммунные заболевания нервной системы </li><li class="list-group-item"> Клинические исследования новых лекарств </li><li class="list-group-item"> Фундаментальные и экспериментальные исследования </li></ul></div></div><div class="card mb-4"><div class="card-body"><h2 class="h4">Условия участия</h2><p> Тезисы принимаются до <strong>1 октября 2018 г.</strong> на адрес <a href="mailto:kremlinneurology@yandex.ru">kremlinneurology@yandex.ru</a>.<br> Формат файлов: MS Word&#39;95 и выше (*.doc, *.docx). Публикация бесплатная. </p><p> Участникам в возрасте до 35 лет доступна &quot;Школа молодых ученых&quot; с возможностью выступления и получения памятных наград. </p></div></div><div class="card mb-4"><div class="card-body"><h2 class="h4">Дополнительные мероприятия</h2><p> В рамках конференции пройдет II сателлитный симпозиум &quot;Сестринское дело&quot; — лекции и мастер-классы по сестринским манипуляциям. </p></div></div><div class="card mb-4"><div class="card-body"><h2 class="h4">Организационная информация</h2><p> Предварительная регистрация и онлайн-трансляция на сайте <a href="https://www.medq.ru" target="_blank">www.medq.ru</a> в разделе &quot;Конференции&quot;. </p><p> Провайдер мероприятия: ООО &quot;Медзнания&quot;, г. Москва, Большой Каретный пер., 7<br> Тел: (495) 699-14-65, (495) 699-81-84<br> Email: <a href="mailto:info@medq.ru">info@medq.ru</a></p></div></div>',8)]))}const n=i(c,[["render",d]]);export{n as default};
